source('bootstrap.R', local = TRUE)
for (f in c('mod_kosten_signalen','mod_elektriciteit','mod_gas','mod_water','app_ui','app_server')) {
  source(file.path('modules', paste0(f, '.R')), local = TRUE)
}
shiny::shinyApp(ui = app_ui(), server = app_server)

plotly_dependency <- function() {
  p <- plotly::plot_ly(
    x = 1,
    y = 1,
    type = "scatter",
    mode = "markers"
  )

  htmltools::tagList(
    htmltools::findDependencies(
      htmltools::as.tags(p)
    )
  )
}

app_ui <- function() {
  primary <- cfg_get('theme', 'primary', default = '#0F766E')
  theme <- bslib::bs_theme(version = 5, primary = primary,
    base_font = 'system-ui', heading_font = 'system-ui')
  page <- function(title, subtitle, type, content) {
    div(class = paste('content-wrap', type),
        style = paste0('--section-accent:', cfg_get('theme', type, default = primary)),
        div(class = 'page-heading', tags$small('GROBBEN VERBRUIK / DASHBOARD'),
            tags$h1(title), tags$p(subtitle)), content)
  }
  fluidPage(
    theme = theme,

    # BEGIN GROBBEN MOBILE CHARTS
    tags$head(tags$script(HTML(r"---(/* Grobben mobile charts: keep the original Shiny widget and its events. */
(() => {
  'use strict';
  if (window.grobbenMobileCharts) return;
  window.grobbenMobileCharts = true;
  let active = null, scheduled = false, resizeTimer;
  const selector = '.plotly.html-widget-output, .plotly.shiny-bound-output';
  const ready = g => window.Plotly && g && g._fullLayout && Array.isArray(g.data);
  const button = (label, title, fn) => {
    const b = document.createElement('button');
    b.type = 'button'; b.textContent = label; b.title = title;
    b.setAttribute('aria-label', title); b.addEventListener('click', fn);
    return b;
  };
  function resize(g) {
    if (!ready(g)) return;
    requestAnimationFrame(() => requestAnimationFrame(() => {
      if (ready(g) && g.getBoundingClientRect().width > 0)
        Promise.resolve(window.Plotly.Plots.resize(g)).catch(console.warn);
    }));
  }
  function axes(g) {
    return Object.keys(g._fullLayout).filter(k => /^(x|y)axis\d*$/.test(k) && Array.isArray(g._fullLayout[k].range));
  }
  function relayout(g, changes) {
    if (ready(g)) Promise.resolve(window.Plotly.relayout(g, changes)).catch(console.warn);
  }
  function zoom(g, factor) {
    if (!ready(g)) return;
    const changes = {};
    axes(g).forEach(k => {
      const a = g._fullLayout[k];
      if (a.fixedrange) return;
      const date = a.type === 'date';
      const nums = a.range.map(v => date ? Date.parse(String(v).replace(' ', 'T') + (/Z$|[+-]\d\d:\d\d$/.test(String(v)) ? '' : 'Z')) : Number(v));
      if (!nums.every(Number.isFinite)) return;
      const mid = (nums[0] + nums[1]) / 2;
      changes[k + '.range'] = nums.map(v => {
        const n = mid + (v-mid)*factor;
        return date ? new Date(n).toISOString() : n;
      });
      changes[k + '.autorange'] = false;
    });
    if (Object.keys(changes).length) relayout(g, changes);
  }
  function close() {
    if (!active) return;
    const a = active; active = null;
    a.panel.classList.remove('gmc-full');
    document.body.classList.remove('gmc-lock');
    a.open.hidden = false; a.tools.hidden = true;
    a.open.setAttribute('aria-expanded','false');
    a.open.focus({preventScroll:true});
    resize(a.g);
  }
  function open(a) {
    if (!ready(a.g)) return;
    if (active) close();
    active = a;
    a.initial = {};
    axes(a.g).forEach(k => {
      const axis = a.g._fullLayout[k];
      a.initial[k+'.autorange'] = axis.autorange;
      if (!axis.autorange) a.initial[k+'.range'] = axis.range.slice();
    });
    a.initial.dragmode = a.g._fullLayout.dragmode;
    a.panel.classList.add('gmc-full');
    document.body.classList.add('gmc-lock');
    a.open.hidden = true; a.tools.hidden = false;
    a.open.setAttribute('aria-expanded','true');
    a.exit.focus({preventScroll:true});
    resize(a.g);
  }
  function scan() {
    scheduled = false;
    document.querySelectorAll(selector).forEach(g => {
      if (g.dataset.gmc) return;
      const panel = g.closest('.panel');
      if (!panel || panel.querySelectorAll(selector).length !== 1) return;
      const toolbar = document.createElement('div'); toolbar.className = 'gmc-bar';
      const tools = document.createElement('div'); tools.className = 'gmc-tools'; tools.hidden = true;
      const a = {g, panel, tools};
      a.open = button('⛶ Vergroten', 'Grafiek schermvullend openen', () => open(a));
      a.open.setAttribute('aria-expanded','false');
      a.exit = button('✕ Sluiten', 'Schermvullende grafiek sluiten', close);
      tools.append(button('＋', 'Inzoomen', () => zoom(g,.7)), button('−', 'Uitzoomen', () => zoom(g,1/.7)),
        button('Schuiven', 'Verschuifmodus', () => relayout(g,{dragmode:'pan'})),
        button('Zoom', 'Selecteer een zoomgebied', () => relayout(g,{dragmode:'zoom'})),
        button('↺', 'Oorspronkelijke assen herstellen', () => relayout(g,a.initial || {})), a.exit);
      toolbar.append(a.open,tools); g.before(toolbar); g.dataset.gmc = '1';
    });
    if (active && !active.g.isConnected) close();
  }
  function schedule() { if (!scheduled) { scheduled = true; requestAnimationFrame(scan); } }
  function start() {
    new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});
    schedule();
    document.addEventListener('keydown', e => { if (e.key === 'Escape' && active) close(); });
    window.addEventListener('resize', () => { clearTimeout(resizeTimer); resizeTimer = setTimeout(() => { if(active) resize(active.g); },150); });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded',start,{once:true}); else start();
})();
)---"))),
    # END GROBBEN MOBILE CHARTS
    plotly_dependency(),
    tags$head(tags$link(rel = 'stylesheet', href = 'style.css'),
      tags$style(HTML(paste0(':root{--accent:', primary, ';--bg-page:', cfg_get('theme','background',default='#F3F6F4'), ';}'))),
      tags$script(HTML("document.addEventListener('mouseover', function(e) { var el=e.target.closest('[data-bs-toggle=popover]'); if(el && window.bootstrap && !bootstrap.Popover.getInstance(el)){ bootstrap.Popover.getOrCreateInstance(el).show(); } });"))),
    div(class = 'app-shell',
      div(class = 'app-sidebar',
        div(class = 'brand', span(class = 'brand__logo', icon('bolt')),
          div(tags$strong('Grobben'), tags$small('VERBRUIK'))),
        tags$button(type = 'button', class = 'mobile-menu-toggle',
          `aria-label` = 'Navigatiemenu', `aria-expanded` = 'false',
          `aria-controls` = 'mobile-navigation',
          onclick = "var nav = document.getElementById('mobile-navigation'); var open = nav.classList.toggle('is-open'); this.setAttribute('aria-expanded', String(open));",
          icon('bars')),
        div(id = 'mobile-navigation', class = 'mobile-navigation',
          tags$div(class = 'nav-label', 'DASHBOARDS'),
          actionLink('nav_electricity', tagList(icon('bolt'), span('Elektriciteit')), class = 'side-link electricity'),
          actionLink('nav_gas', tagList(icon('fire'), span('Gas')), class = 'side-link gas'),
          actionLink('nav_water', tagList(icon('tint'), span('Water')), class = 'side-link water')),
        tags$script(HTML("document.addEventListener('click', function(e) { if(e.target.closest('#mobile-navigation .side-link')) { document.getElementById('mobile-navigation').classList.remove('is-open'); document.querySelector('.mobile-menu-toggle').setAttribute('aria-expanded', 'false'); } });")),
        div(class = 'snapshot-date', paste('Bijgewerkt:', format(VERBRUIK_SNAPSHOT$metadata$exported_at, '%d-%m-%Y %H:%M', tz='Europe/Amsterdam'))),
        div(class = 'sidebar-footer', icon('chart-line'), ' Energie & water')),
      div(class = 'app-main',
        tabsetPanel(id = 'main_nav', type = 'hidden',
          tabPanel('Elektriciteit', page('Elektriciteit', 'Inzicht in stroomverbruik, teruglevering en kosten.', 'electricity', mod_elektriciteit_ui('use'))),
          tabPanel('Gas', page('Gas', 'Volg gasverbruik, temperatuur en jaarlijkse kosten.', 'gas', mod_gas_ui('gas'))),
          tabPanel('Water', page('Water', 'Inzicht in waterverbruik en ontwikkelingen per jaar.', 'water', mod_water_ui('water')))))))
}

# Grobben Verbruik: gedeelde maandkosten en signaleringen.
# Alleen-lezen: deze functies passen SQLite nooit aan.

gv_essent_maandkosten <- function(data_version) {
  data_version()
  x <- VERBRUIK_SNAPSHOT$tables[['essent_maandrapport']]
  if (is.null(x)) return(data.frame())
  required <- c('jaar','maand','kosten_stroom','kosten_gas',
                'kosten_stroom_vast','kosten_stroom_variabel',
                'kosten_gas_vast','kosten_gas_variabel')
  if (!all(required %in% names(x))) return(data.frame())
  x$jaar <- suppressWarnings(as.integer(x$jaar))
  x$maand <- suppressWarnings(as.integer(x$maand))
  cols <- setdiff(required,c('jaar','maand'))
  for (nm in cols) x[[nm]] <- to_num(x[[nm]])
  x <- x[!is.na(x$jaar) & !is.na(x$maand) & x$maand %in% 1:12, required, drop = FALSE]
  x[order(x$jaar,x$maand),,drop=FALSE]
}

gv_geld <- function(x) {
  if (!length(x) || is.na(x) || !is.finite(x)) return('–')
  paste0('€ ',format(round(x,2),big.mark='.',decimal.mark=',',nsmall=2,trim=TRUE))
}

gv_kosten_plot <- function(k, year, soort = c('stroom','gas')) {
  soort <- match.arg(soort)
  shiny::validate(shiny::need(nrow(k)>0, 'Nog geen Essent-maandrapporten met kostenuitsplitsing geïmporteerd.'))
  d <- k[k$jaar == year,,drop=FALSE]
  shiny::validate(shiny::need(nrow(d)>0, 'Geen Essent-kosten voor het geselecteerde jaar.'))
  names <- c('jan','feb','mrt','apr','mei','jun','jul','aug','sep','okt','nov','dec')
  vaste <- d[[paste0('kosten_',soort,'_vast')]]
  variabele <- d[[paste0('kosten_',soort,'_variabel')]]
  totaal <- d[[paste0('kosten_',soort)]]
  shiny::validate(shiny::need(any(!is.na(totaal)), 'Geen maandkosten beschikbaar.'))
  x <- d$maand
  kleur <- if (soort=='gas') '#BB785A' else '#B58A35'
  p <- plotly::plot_ly()
  if (any(!is.na(vaste))) p <- plotly::add_trace(p,x=x,y=vaste,type='bar',name='Vaste kosten',
    marker=list(color='#AAB7C5'),hovertemplate='%{x}<br>Vaste kosten: € %{y:.2f}<extra></extra>')
  if (any(!is.na(variabele))) p <- plotly::add_trace(p,x=x,y=variabele,type='bar',name='Variabele kosten',
    marker=list(color=kleur),hovertemplate='%{x}<br>Variabele kosten: € %{y:.2f}<extra></extra>')
  p <- plotly::add_trace(p,x=x,y=totaal,type='scatter',mode='lines+markers',name='Totaal',
    line=list(shape='spline',smoothing=0.65,color='#526A81',width=3),
    marker=list(color='#526A81',size=7),connectgaps=FALSE,
    hovertemplate='%{x}<br>Totaal: € %{y:.2f}<extra></extra>')
  plotly::layout(p,barmode='relative',
    xaxis=list(title='Maand',tickmode='array',tickvals=1:12,ticktext=names,range=c(0.5,12.5)),
    yaxis=list(title='Maandkosten (€)',zeroline=TRUE,zerolinecolor='#94A3B8'),
    legend=list(orientation='h',y=-0.22),
    margin=list(l=65,r=25,t=12,b=82),
    paper_bgcolor='rgba(0,0,0,0)',plot_bgcolor='rgba(0,0,0,0)')
}

gv_signaalkaart <- function(berichten) {
  if (!length(berichten)) return(tags$div(class='elek-new-hint',
    'Geen opvallende afwijkingen gevonden in de beschikbare vergelijkbare maanden.'))
  tags$div(style='display:grid;gap:9px;',lapply(berichten,function(m)
    tags$div(style='padding:12px 15px;border:1px solid #DCE5ED;border-left:3px solid #526A81;border-radius:9px;background:#F8FAFC;color:#334155;',m)))
}

# Signaleringsdrempels staan in config/config.yml onder 'signaleringen'.
# Als een instelling ontbreekt blijft het bestaande gedrag behouden.
gv_signaal_drempel <- function(naam, standaard, min_waarde = 0) {
  waarde <- tryCatch(
    cfg_get('signaleringen', naam, default = standaard),
    error = function(e) standaard
  )
  waarde <- suppressWarnings(as.numeric(waarde))
  if (length(waarde) != 1L || is.na(waarde) || !is.finite(waarde) || waarde < min_waarde) {
    warning(sprintf('Ongeldige signaleringen-instelling %s; standaardwaarde %s gebruikt.', naam, standaard),
            call. = FALSE)
    return(standaard)
  }
  waarde
}

gv_vergelijk_laatste_maand <- function(d, veld, naam, eenheid, minimum = 0, grens = 15) {
  grens <- gv_signaal_drempel('verbruik_pct', grens)
  sleutel <- c(afname='minimum_stroom_kwh', terug='minimum_teruglevering_kwh',
              gas='minimum_gas_m3', water='minimum_water_m3')[[veld]]
  if (!is.null(sleutel)) minimum <- gv_signaal_drempel(sleutel, minimum)
  # Vergelijk alleen werkelijk geregistreerde gelijke kalendermaanden.
  d <- d[!is.na(d[[veld]]) & is.finite(d[[veld]]),,drop=FALSE]
  if (!nrow(d)) return(NULL)
  d <- d[order(d$Jaar,d$MaandNum,decreasing=TRUE),,drop=FALSE]
  for (i in seq_len(nrow(d))) {
    cur <- d[i,,drop=FALSE]
    prev <- d[d$Jaar == cur$Jaar-1L & d$MaandNum == cur$MaandNum,,drop=FALSE]
    if (!nrow(prev) || is.na(prev[[veld]][1]) || prev[[veld]][1]<=0) next
    diff <- cur[[veld]][1] - prev[[veld]][1]
    pct <- 100*diff/prev[[veld]][1]
    if (abs(pct)<grens || abs(diff)<minimum) return(NULL)
    return(sprintf('%s: %s %.0f%% dan in dezelfde maand vorig jaar (%.0f tegenover %.0f %s).',
      naam,if(pct>0)'hoger' else 'lager',abs(pct),cur[[veld]][1],prev[[veld]][1],eenheid))
  }
  NULL
}

gv_kosten_signaal <- function(k, d, soort, veld) {
  minder_verbruik_pct <- gv_signaal_drempel('kosten_minder_verbruik_pct', 5)
  hogere_kosten_pct <- gv_signaal_drempel('kosten_stijging_pct', 10)
  hogere_kosten_euro <- gv_signaal_drempel('kosten_stijging_euro', 5)
  if (!nrow(k) || !nrow(d)) return(NULL)
  kostenveld <- paste0('kosten_',soort)
  k <- k[!is.na(k[[kostenveld]]) & is.finite(k[[kostenveld]]),,drop=FALSE]
  k <- k[order(k$jaar,k$maand,decreasing=TRUE),,drop=FALSE]
  for (i in seq_len(nrow(k))) {
    cur <- k[i,,drop=FALSE]
    prv <- k[k$jaar==cur$jaar-1L & k$maand==cur$maand,,drop=FALSE]
    if (!nrow(prv) || is.na(prv[[kostenveld]][1]) || prv[[kostenveld]][1]<=0) next
    x <- d[d$Jaar==cur$jaar & d$MaandNum==cur$maand,,drop=FALSE]
    y <- d[d$Jaar==cur$jaar-1L & d$MaandNum==cur$maand,,drop=FALSE]
    if (!nrow(x) || !nrow(y) || is.na(x[[veld]][1]) || is.na(y[[veld]][1]) || y[[veld]][1]<=0) next
    if (x[[veld]][1] <= (1 - minder_verbruik_pct / 100) * y[[veld]][1] &&
        cur[[kostenveld]][1] >= (1 + hogere_kosten_pct / 100) * prv[[kostenveld]][1] &&
        cur[[kostenveld]][1] - prv[[kostenveld]][1] >= hogere_kosten_euro) {
      return(sprintf('Kosten stijgen ondanks lager verbruik: %.0f%% minder %s, maar %s tegenover %s in dezelfde maand vorig jaar.',
        100*(1-x[[veld]][1]/y[[veld]][1]),if(soort=='gas')'gas' else 'netafname',
        gv_geld(cur[[kostenveld]][1]),gv_geld(prv[[kostenveld]][1])))
    }
  }
  NULL
}

:root {
  --accent: #0f766e;
  --bg-page: #f3f6f4;
  --bg-card: #ffffff;
  --text: #163047;
  --text-muted: #64748b;
  --line: #dbe4e8;
  --radius: 16px;
  --shadow: 0 6px 18px rgba(15,23,42,.06);
}
html, body { height:100%; margin:0; padding:0; background:var(--bg-page); color:var(--text); font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; font-size:15px; -webkit-font-smoothing:antialiased; }
body > .container-fluid { padding:0; }
.app-shell { min-height:100vh; }
.app-sidebar { position:fixed; inset:0 auto 0 0; width:250px; background:var(--accent,#0f766e); color:white; padding:26px 18px; display:flex; flex-direction:column; gap:8px; z-index:1000; box-shadow:2px 0 18px rgba(15,23,42,.12); }
.app-main { margin-left:250px; min-width:0; }
.brand { display:flex; align-items:center; gap:12px; margin:0 0 28px; padding:0 6px; }
.brand__logo { display:inline-flex; align-items:center; justify-content:center; width:42px; height:42px; border-radius:12px; background:rgba(255,255,255,.18); color:white; font-size:20px; }
.brand strong { display:block; font-size:24px; line-height:1.05; letter-spacing:-.6px; color:white; }
.brand small { display:block; font-size:10px; letter-spacing:2px; color:rgba(255,255,255,.75); }
.nav-label { font-size:10px; letter-spacing:1.5px; color:rgba(255,255,255,.7); padding:2px 10px 8px; }
.app-sidebar a.side-link { display:flex !important; align-items:center; gap:12px; padding:12px 14px; border-radius:12px; color:white !important; text-decoration:none !important; font-weight:600; background:transparent; transition:background .15s ease; }
.app-sidebar a.side-link:hover,.app-sidebar a.side-link:focus { background:rgba(255,255,255,.14); }
.app-sidebar a.side-link i { width:18px; text-align:center; }
.app-sidebar a.side-link.electricity i { color:#facc15; }
.app-sidebar a.side-link.gas i { color:#fb923c; }
.app-sidebar a.side-link.water i { color:#38bdf8; }
.snapshot-date { margin-top:12px; padding:0 12px; font-size:12px; color:rgba(255,255,255,.82); }
.sidebar-footer { margin-top:auto; padding:12px; font-size:12px; color:rgba(255,255,255,.72); }
.content-wrap { padding:30px 30px 42px; max-width:1700px; }
.page-heading { margin-bottom:22px; }
.page-heading small { display:block; font-size:10px; font-weight:700; letter-spacing:1.5px; color:var(--section-accent,var(--accent)); }
.page-heading h1 { margin:6px 0 8px; font-size:30px; font-weight:750; letter-spacing:-.8px; color:#14324a; }
.page-heading p { margin:0; color:var(--text-muted); font-size:14px; }
.panel { height:100%; background:var(--bg-card); border:1px solid var(--line); border-radius:var(--radius); box-shadow:var(--shadow); overflow:hidden; }
.panel__head { background:white; padding:16px 18px 10px; border-bottom:1px solid #edf2f5; font-size:12px; font-weight:700; color:#35506a; }
.panel__body { padding:16px 18px 18px; min-width:0; }
.page-heading + .row .panel { border-top:4px solid var(--section-accent,var(--accent)); }
.kpi-box { min-height:110px; display:flex; flex-direction:column; justify-content:space-between; gap:8px; }
.kpi-value { font-size:30px; line-height:1.08; font-weight:750; letter-spacing:-.8px; color:#14324a; }
.kpi-sub { font-size:13px; color:var(--text-muted); }
.kpi-footer { margin-top:6px; padding-top:8px; border-top:1px solid #edf2f5; font-size:12px; color:#52667c; }
.plotly,table.dataTable { box-shadow:none; }
.dataTable thead th { background:#f3f6f9; color:#486072; font-size:12px; border-bottom:1px solid #dde7ee !important; }
.dataTable tbody td { padding:10px !important; }
.elek-new-hint,.elek-new-note { font-size:12px; color:var(--text-muted); }
.elek-new-tools { display:flex; align-items:end; flex-wrap:wrap; gap:16px; margin-bottom:12px; }
.elek-new-tools .form-group { margin-bottom:0; }
.mobile-menu-toggle { display:none; }
.mobile-navigation { display:flex; flex-direction:column; gap:6px; }
@media (max-width:900px) {
  .app-sidebar { position:sticky; top:0; width:100%; display:block; padding:16px; z-index:1050; box-shadow:0 4px 12px rgba(0,0,0,.10); }
  .brand { margin:0; padding-right:55px; }
  .mobile-menu-toggle { display:flex; align-items:center; justify-content:center; position:absolute; top:16px; right:16px; width:44px; height:44px; border:1px solid rgba(255,255,255,.20); border-radius:12px; background:rgba(255,255,255,.12); color:white; font-size:20px; cursor:pointer; }
  .mobile-menu-toggle:hover { background:rgba(255,255,255,.22); }
  .mobile-navigation { display:none; margin-top:16px; padding-top:12px; border-top:1px solid rgba(255,255,255,.15); }
  .mobile-navigation.is-open { display:flex; }
  .mobile-navigation .side-link { width:100%; min-height:48px; background:rgba(255,255,255,.08); margin-bottom:4px; }
  .app-sidebar a.side-link { padding:10px 12px; }
  .snapshot-date { margin-top:10px; padding:0 6px; font-size:11px; }
  .sidebar-footer { display:none; }
  .app-main { margin-left:0; }
  .content-wrap { padding:18px; }
  .kpi-value { font-size:24px; }
  .panel__body { overflow-x:auto; }
}

/* BEGIN GROBBEN MOBILE CHARTS */
/* Grobben mobile charts */
.gmc-bar { display:flex; justify-content:flex-end; margin:0 0 8px; }
.gmc-bar button { border:1px solid #cbd5e1; border-radius:9px; background:#fff; color:#163047; min-height:44px; min-width:44px; padding:7px 11px; font:600 13px system-ui,sans-serif; cursor:pointer; }
.gmc-bar button:focus-visible { outline:3px solid #0f766e; outline-offset:2px; }
.gmc-tools { display:flex; flex-wrap:wrap; gap:6px; justify-content:flex-end; }
